/* ZimiGames Spanish courts: the sota, caballo and rey of the four Spanish suits (coins, cups, swords, clubs), from the
   "Jeu d'Aluette" printed by B. P. Grimaud in France in 1860 (a Spanish-suited pack), as scanned by the Bibliotheque nationale de France
   (Gallica, https://gallica.bnf.fr/ark:/12148/btv1b10513825g and its siblings) and published on Wikimedia Commons, category
   "Modern Spanish Catalan deck - Grimaud - 1860", files "Jeu d'Aluette - Grimaud - 1860 - Jack|Knight|King of Coins|Cups|Swords|Clubs.jpg".
   Public domain (a 19th-century print, tagged PD-Art there); no licence applies, no credit is required, and we give one.
   Each scan is cut to the inside of its printed frame (the frame itself, whose corners were broken where the print sets its number, is
   left out: cards.js draws a clean rule in its place), the printed number is painted out with the paper, and the paper alone is lifted to the
   card's cream (#fdfcf8): the colour and the ink keep the scan's own strength (a little more saturated, as a modern print is), so the
   figures read like a Fournier pack's. 268 px wide, stored as WebP, about 25 KB each. cards.js asks for markup(k, suit)
   (k 7 sota, 8 caballo, 9 rey; suits as ITALIAN_SUITS) and falls back to its own drawing when this file is not loaded. */
(function (root) {
  'use strict';

  // The picture: the figure and its ground inside the frame, with a little paper round it. The window is as wide as the frame between
  // the index's two margin columns (cards.js passes the column's width) and its height follows from the picture's own shape.
  var SCAN_W = 268, SCAN_H = 459, COLUMN = 22, FRAME = '#1b1b1b', FRAME_W = 0.5;
  var WEBP = 'data:image/webp;base64,';
  var ART = {
    '7,0': '',
    '7,1': '',
    '7,2': '',
    '7,3': '',
    '8,0': '',
    '8,1': '',
    '8,2': '',
    '8,3': '',
    '9,0': '',
    '9,1': '',
    '9,2': '',
    '9,3': ''
  };

  function picture(k, suit, x, y, w, h) {
    var data = ART[k + ',' + suit];
    return data ? '<image href="' + WEBP + data + '" x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" preserveAspectRatio="none"/>' : '';
  }
  // The big card: the picture in a clean, continuous rule (a whole device pixel, never smeared: cards.css .zc-rule), centred between the columns.
  function markup(k, suit, column) {
    var w = 100 - 2 * (column || COLUMN), h = Math.round(w * SCAN_H / SCAN_W * 2) / 2, x = (100 - w) / 2, y = (140 - h) / 2;
    var i = FRAME_W / 2; // the rule runs inside the picture's edge, so its outer edge is the column's edge
    return picture(k, suit, x, y, w, h) + '<rect x="' + (x + i) + '" y="' + (y + i) + '" width="' + (w - FRAME_W) + '" height="' + (h - FRAME_W) + '" fill="none" class="zc-rule" stroke="' + FRAME + '" stroke-width="' + FRAME_W + '"/>';
  }
  // The small card (about 40 px wide): the same picture, smaller, under the big index row.
  var THUMB_Y = 38, THUMB_H = 97, THUMB_W = Math.round(THUMB_H * SCAN_W / SCAN_H * 100) / 100;
  function thumb(k, suit) { return picture(k, suit, (100 - THUMB_W) / 2, THUMB_Y, THUMB_W, THUMB_H); }

  var api = { markup: markup, thumb: thumb };
  root.ZimiSpanishCourts = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof window !== 'undefined' ? window : globalThis);
